export function preset(id: string): BuildPreset | undefined {
  return PRESETS[id]
}

/** recommended team variants for a kit ([] when none) */
export function presetTeams(id: string): string[][] {
  return TEAM_PRESETS[id] ?? []
}

/** kits whose own kit needs an EARLIER-slot ally of a given Path (Participant-ID gate):
 *  the carrier's slot decides the gate, so its position in the sim team is load-bearing.
 *  evanescia A2 — only an Elation-Skill teammate with a LOWER Participant ID converts CB. */
export const PID_GATE_LEAD: Record<string, string> = { evanescia: 'Elation' }

/** Preset team in SIM order. Returns a COPY (callers pad it up to 4 characters).
 *  Puts the carrier in when the wiki teams omit it, and moves a gated carrier
 *  behind the first qualifying ally. Teams that already satisfy the gate keep their order. */
export function presetTeamOrder(id: string, mates: string[]): string[] {
  const team = mates.includes(id) ? mates.slice() : [id, ...mates]
  const gate = PID_GATE_LEAD[id]
  if (!gate) return team
  const at = team.indexOf(id)
  const lead = team.findIndex((m, i) => i < at && KIT_PATH[m] === gate)
  if (lead >= 0) return team
  const first = team.findIndex((m) => m !== id && KIT_PATH[m] === gate)
  if (first < 0) return team
  team.splice(at, 1)
  team.splice(first, 0, id)
  return team
}

import { KIT_PATH } from './kits'
